import{_ as e,o as t,c as o,ag as i}from"./chunks/framework.XeSgnAkN.js";const h=JSON.parse('{"title":"Privacy","description":"","frontmatter":{},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md","lastUpdated":1790583753000}'),s={name:"privacy.md"};function n(r,a,c,l,d,u){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><p>quickbox is local-first.</p><h2 id="stored-data" tabindex="-1">Stored data <a class="header-anchor" href="#stored-data" aria-label="Permalink to &quot;Stored data&quot;">​</a></h2><ul><li>tasks in local markdown files</li><li>app preferences in UserDefaults</li></ul><h2 id="quickbox-cloud-optional" tabindex="-1">quickbox Cloud (optional) <a class="header-anchor" href="#quickbox-cloud-optional" aria-label="Permalink to &quot;quickbox Cloud (optional)&quot;">​</a></h2><p>quickbox Cloud is off until you connect it in Settings. When it is connected:</p><ul><li><strong>What is stored:</strong> your email address, and a copy of your task files and notes. This data lets AI agents you connect (such as Claude) and your other devices use your inbox.</li><li><strong>Where:</strong> on Cloudflare, in a storage unit dedicated to your account. Sign-in codes are sent by email through Resend.</li><li><strong>Who can access it:</strong> only apps and agents you approve on the sign-in page. You can see and disconnect them at any time in Settings → quickbox Cloud → Connected apps.</li><li><strong>Deleting your data:</strong> Settings → quickbox Cloud → Delete account… disconnects every app and agent, then permanently deletes the cloud copy of your tasks and notes and your account. Files in your local folder are not touched.</li><li><strong>Disconnecting a Mac:</strong> this stops syncing and revokes that Mac&#39;s access. Cloud data stays until you delete the account.</li></ul><h2 id="crash-diagnostics" tabindex="-1">Crash diagnostics <a class="header-anchor" href="#crash-diagnostics" aria-label="Permalink to &quot;Crash diagnostics&quot;">​</a></h2><p>Disabled by default.</p><p>When enabled, diagnostics include technical metadata only (version, OS, operation context). Task text content is excluded.</p><h2 id="app-store-disclosure-summary" tabindex="-1">App Store disclosure summary <a class="header-anchor" href="#app-store-disclosure-summary" aria-label="Permalink to &quot;App Store disclosure summary&quot;">​</a></h2><ul><li>quickbox does not track users across apps or websites.</li><li>quickbox does not collect task content for analytics or advertising.</li><li>With quickbox Cloud connected, your email address and task content are stored to provide sync and agent access. They are linked to your account, never used for tracking, and deleted with the account.</li><li>Crash diagnostics are optional and controlled by the user.</li><li>Privacy manifest is provided via <code>quickbox/PrivacyInfo.xcprivacy</code>.</li></ul>',12)])])}const y=e(s,[["render",n]]);export{h as __pageData,y as default};
